"""matplotlib._constrained_layout — layout engine stub.

Plotly handles layout autosizing itself, so we accept the constrained-
layout API calls and emit no-ops. Any script that calls
`fig.set_constrained_layout(True)` or uses `constrained_layout=True`
in `plt.subplots(...)` lands here.
"""


def do_constrained_layout(fig, h_pad=None, w_pad=None,
                          hspace=None, wspace=None,
                          rect=(0, 0, 1, 1), compress=False):
    """Run a single constrained-layout pass. The plotly backend
    handles axis autosizing itself; we use the requested pads to
    update the figure's :class:`SubplotParams` (so anything that
    reads them back gets sensible values) and return the layout dict.
    """
    if fig is None:
        return None
    # Convert pads (in inches) to figure-fraction approximations.
    size = fig.get_size_inches() if hasattr(fig, 'get_size_inches') else (8, 6)
    w_frac = (w_pad or 0.0) / max(size[0], 1e-9)
    h_frac = (h_pad or 0.0) / max(size[1], 1e-9)
    layout = {
        'rect': tuple(rect),
        'w_pad': w_pad, 'h_pad': h_pad,
        'wspace': wspace, 'hspace': hspace,
        'w_frac': w_frac, 'h_frac': h_frac,
        'compress': bool(compress),
    }
    try:
        fig.subplots_adjust(
            left=rect[0] + w_frac,
            bottom=rect[1] + h_frac,
            right=rect[0] + rect[2] - w_frac,
            top=rect[1] + rect[3] - h_frac,
            wspace=wspace,
            hspace=hspace,
        )
    except Exception:
        pass
    return layout


def get_pos_and_bbox(ax, renderer):
    """Return ``(position, tight_bbox)`` for ``ax``. Position is the
    axes' figure-fraction rectangle; tight_bbox is its visible window
    extent. Both are :class:`Bbox` instances when computable, else None."""
    from matplotlib.transforms import Bbox
    pos = None; tbb = None
    try:
        # Axes.get_position() typically returns a Bbox or (x, y, w, h).
        p = ax.get_position()
        if hasattr(p, 'x0'):
            pos = p
        else:
            x, y, w, h = p
            pos = Bbox.from_extents(x, y, x + w, y + h)
    except Exception:
        pass
    try:
        tbb = ax.get_tightbbox(renderer)
    except Exception:
        pass
    return pos, tbb


def layoutcols_from_gridspec(gs):
    """Return the column count for a gridspec, used by the layout
    solver to size its column array."""
    if gs is None:
        return []
    try:
        nrows, ncols = gs.get_geometry()
        return list(range(ncols))
    except Exception:
        return []


def make_layoutgrids(fig, layoutgrids=None, suppress_warnings=False):
    """Build the per-gridspec layout-grid dict the solver uses.
    Returns ``{gs: LayoutGrid}`` for every gridspec attached to ``fig``."""
    layoutgrids = dict(layoutgrids or {})
    if fig is None:
        return layoutgrids
    # Walk the figure's axes — each one points at a SubplotSpec which in
    # turn points at a GridSpec. Index each unique GridSpec.
    try:
        axes = fig.get_axes()
    except Exception:
        axes = []
    for ax in axes:
        gs = None
        try: gs = ax.get_gridspec()
        except Exception: pass
        if gs is None: continue
        if gs not in layoutgrids:
            layoutgrids[gs] = {'gridspec': gs,
                                'nrows': gs.nrows,
                                'ncols': gs.ncols}
    return layoutgrids


def make_layoutgrids_gs(layoutgrids, gs):
    """Register ``gs`` in ``layoutgrids`` if not already present."""
    layoutgrids = dict(layoutgrids or {})
    if gs is None:
        return layoutgrids
    if gs not in layoutgrids:
        layoutgrids[gs] = {'gridspec': gs,
                            'nrows': getattr(gs, 'nrows', 1),
                            'ncols': getattr(gs, 'ncols', 1)}
    return layoutgrids


