def check_no_collapsed_axes(layout, axes_grid=None):
    """Check no row/column in a constrained layout has collapsed to
    zero size. The shim doesn't actually run the constraint solver,
    so we always report 'no collapse' (returns False)."""
    return False


def colorbar_get_pad(layout, cax):
    """Return the colorbar padding (gap between the parent axes and
    the colorbar). Upstream computes from layout metadata; we return
    the default 0.05."""
    return 0.05


def compress_fixed_aspect(layout, fig, h_pad, w_pad):
    """Shrink subplots that have a fixed aspect so they fit cleanly
    in the figure. No-op in the shim — plotly handles aspect natively."""
    pass


def get_cb_parent_spans(cax):
    """Return the row/column span of the parent axes for a colorbar.
    Best-effort fallback returns ``(0, 1, 0, 1)`` — full extent."""
    return 0, 1, 0, 1


def get_margin_from_padding(obj, *, w_pad=0, h_pad=0, hspace=0, wspace=0):
    """Compute the margin a constrained-layout cell needs given the
    requested padding. Returns ``(left, right, bottom, top)``."""
    return w_pad / 2, w_pad / 2, h_pad / 2, h_pad / 2


